from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # Used leave days: {(employee, year): days_used}
        self._used: dict[tuple[str, int], int] = {}

    def _is_leave_day(self, d: date) -> bool:
        # Weekend check: Monday=0 ... Sunday=6
        if d.weekday() >= 5:
            return False
        if d in self.holidays:
            return False
        return True

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date.")

        # Rule 4: must be made at least 3 days before start
        if (start - today).days < 3:
            raise ValueError(
                "Leave must be requested at least 3 days before the start date."
            )

        # Count leave days across the request (may span multiple years)
        counts: dict[int, int] = {}
        d = start
        one_day = timedelta(days=1)
        while d <= end:
            if self._is_leave_day(d):
                counts[d.year] = counts.get(d.year, 0) + 1
            d += one_day

        # Validate remaining for each year touched, then commit
        for year, n in counts.items():
            key = (employee, year)
            used = self._used.get(key, 0)
            if used + n > self.days_per_year:
                raise ValueError(
                    f"Insufficient leave for {employee} in {year}: "
                    f"requested {n}, available {self.days_per_year - used}."
                )

        for year, n in counts.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + n

        return sum(counts.values())

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return self.days_per_year - used
